// ICP auto-scoring: find companies in Company Database without an ICP Scoring record and score them
// conservatively with the existing framework. Writes only to input columns; formulas do the totals.
const SHEET = 'YOUR_SPREADSHEET_ID';
const MAX_ATTEMPTS = 3;
const vr = $input.first().json.valueRanges || [];
const db = (vr[0] && vr[0].values) || [];
const scored = (vr[1] && vr[1].values) || [];
const settings = (vr[2] && vr[2].values) || [];
const log = (vr[3] && vr[3].values) || [];

const norm = s => String(s == null ? '' : s).trim().replace(/\s+/g, ' ').toLowerCase();
const POINTS_PER_DRIVER = Number(settings[3] && settings[3][0]); // ICP Scoring!B7
if (!POINTS_PER_DRIVER) throw new Error('Could not read scoring settings (ICP Scoring!B4:B9). Nothing was written.');

const existing = new Set(scored.map(r => norm(r[0])).filter(Boolean));
let nextRow = 12 + scored.length; // first empty row after the last scoring record
const errCount = {}; const gaveUp = new Set(); const skipLogged = new Set();
for (const r of log) {
  const n = norm(r[1]);
  if (r[2] === 'error') errCount[n] = (errCount[n] || 0) + 1;
  if (r[2] === 'gave up') gaveUp.add(n);
  if (r[2] === 'skipped') skipLogged.add(n);
}

const host = u => { const m = String(u == null ? '' : u).trim().match(/^https?:\/\/([^\/?#:\s]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
const rootOf = h => h.split('.').slice(-2).join('.');
const DRIVERS = [
  ['Failed payments', /\b(failed|declined|unsuccessful)\b/i],
  ['Refunds', /\brefund/i],
  ['Disputes / payment exceptions', /\b(chargebacks?|disputes?|underpa(id|yment)|overpa(id|yment))\b/i],
  ['KYC/KYB or account restrictions', /\b(kyc|kyb|identity verification|verify your identity|account (is )?(restricted|suspended|locked|blocked|deactivated|closed))\b/i],
  ['Settlement / payout issues', /\b(payouts?|settlements?|withdrawals?)\b/i],
];
const COMPLAINT_SITES = ['trustpilot.com', 'g2.com', 'bbb.org', 'financial-ombudsman.org.uk', 'consumeraffairs.com', 'sitejabber.com'];
const MONEY = /(payment|payout|acquir|on-?ramp|off-?ramp|remittance|money transfer|cross-border|gateway|processing|settlement rails)/i;
const OTHER_LINES = /(issuer|exchange|trading|custody|lending|wallet provider|brokerage)/i;
const ADJACENT = /(fintech|financial|bank|crypto|blockchain|stablecoin|wallet)/i;
const SMB = /(consumer|individual|freelancer|end users?|shoppers?|smbs?|small business|self-serve|startups?|creators?|sellers)/i;
const ENT = /(enterprise|institution|banks|psps?|businesses only|large merchants)/i;

function businessFit(text) {
  const t = String(text || '');
  if (!t.trim()) return { pts: 0, why: 'business model missing' };
  const m = t.search(MONEY), o = t.search(OTHER_LINES);
  if (m >= 0 && o >= 0 && o < m) return { pts: 20, why: 'payments is one of several business lines' };
  if (m >= 0) return { pts: 30, why: 'core product moves money' };
  if (ADJACENT.test(t)) return { pts: 10, why: 'adjacent infrastructure' };
  return { pts: 0, why: 'business model does not indicate payments' };
}
function companyScale(text) {
  const t = String(text || '').trim();
  if (!t) return { pts: 0, why: 'size missing' };
  if (/unknown/i.test(t)) return { pts: 4, why: 'size Unknown' };
  const m = t.match(/(\d{1,3}(?:,\d{3})+|\d+)/);
  if (!m) return { pts: 4, why: 'size not parseable, treated as Unknown' };
  const n = Number(m[1].replace(/,/g, ''));
  const pts = n >= 2000 ? 20 : n >= 500 ? 16 : n >= 200 ? 12 : n >= 50 ? 8 : 4;
  return { pts, why: (/est|third-party|~/i.test(t) ? 'est. ' : '') + n.toLocaleString('en-US') + ' employees (low end used)' };
}
function customerType(text) {
  const t = String(text || '');
  if (!t.trim()) return { pts: 0, why: 'target customer missing' };
  const s = SMB.test(t), e = ENT.test(t);
  if (s && e) return { pts: 6, why: 'mixed customer base' };
  if (s) return { pts: 10, why: 'consumer/SMB self-serve' };
  return { pts: 3, why: 'enterprise/business only' };
}

const out = [];
const seen = new Set();
for (const r of db) {
  const company = String(r[0] || '').trim();
  const key = norm(company);
  if (!key) continue;
  if (existing.has(key)) continue;                       // already scored: no duplicate
  if (seen.has(key)) {                                    // same company twice in Company Database
    if (!skipLogged.has(key)) out.push({ json: { action: 'log', company, event: 'skipped', detail: 'Duplicate name in Company Database; only one scoring record is created.', row: '' } });
    continue;
  }
  seen.add(key);
  if ((errCount[key] || 0) >= MAX_ATTEMPTS) {
    if (!gaveUp.has(key)) out.push({ json: { action: 'log', company, event: 'gave up', detail: `Failed ${MAX_ATTEMPTS} times. Needs manual review; delete its error rows here to retry.`, row: '' } });
    continue;
  }

  const website = r[1], model = r[3], target = r[5], size = r[6], sources = String(r[10] || '');
  const fit = businessFit(model), scale = companyScale(size), cust = customerType(target);

  // Support drivers: only from pages on the company's own domain that actually load
  const urls = sources.split(/\s*\|\s*|\s+/).map(s => s.trim()).filter(s => /^https?:\/\//i.test(s));
  const siteRoot = host(website) ? rootOf(host(website)) : '';
  const official = siteRoot ? urls.filter(u => rootOf(host(u)) === siteRoot) : [];
  const found = new Set(); let loaded = 0; const failed = [];
  for (const u of official.slice(0, 6)) {
    try {
      const html = await this.helpers.httpRequest({ method: 'GET', url: u, timeout: 15000, json: false, headers: { 'User-Agent': 'Mozilla/5.0 (ICP research bot)' } });
      const text = String(html).replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
      loaded++;
      DRIVERS.forEach(([name, re], i) => { if (re.test(text)) found.add(i); });
    } catch (e) { failed.push(host(u)); }
  }
  const flags = DRIVERS.map((_, i) => found.has(i));
  const complaintHosts = new Set(urls.map(host).filter(h => COMPLAINT_SITES.some(c => h === c || h.endsWith('.' + c))).map(h => COMPLAINT_SITES.find(c => h === c || h.endsWith('.' + c))));
  const compl = complaintHosts.size >= 2 ? 10 : complaintHosts.size === 1 ? 5 : 0;

  const driverNames = DRIVERS.filter((_, i) => found.has(i)).map(d => d[0].toLowerCase());
  const parts = [
    `Business fit: ${fit.why}`,
    `scale: ${scale.why}`,
    official.length === 0 ? 'support drivers: no official help pages in Source, none counted'
      : `support drivers: ${driverNames.length}/5 found on ${loaded} of ${official.length} official page(s)` + (driverNames.length ? ` (${driverNames.join(', ')})` : '') + (failed.length ? `; ${failed.length} page(s) failed to load` : ''),
    `customer type: ${cust.why}`,
    `complaint sources: ${complaintHosts.size}`,
  ];
  const reason = 'Auto-scored. ' + parts.join('; ') + '. Needs analyst review.';
  const safe = s => (/^[=+\-@]/.test(s) ? "'" + s : s);
  const row = nextRow++;
  const blank0 = n => (n === 0 ? '' : n); // blank counts as 0 in the formulas and passes dropdown validation
  out.push({ json: {
    action: 'create', company, row,
    summary: parts.join('; '),
    data: [
      { range: `'ICP Scoring'!A${row}:H${row}`, values: [[safe(company), blank0(fit.pts), blank0(scale.pts), ...flags]] },
      { range: `'ICP Scoring'!K${row}:L${row}`, values: [[blank0(cust.pts), compl]] },
      { range: `'ICP Scoring'!Q${row}:S${row}`, values: [[reason, 'Auto', 'Needs review']] },
    ],
  } });
}
return out;

const norm = s => String(s == null ? '' : s).trim().replace(/\s+/g, ' ').toLowerCase();
const src = $('Is new record?').item.json;
const v = (($json.values || [])[0]) || [];
const ok = norm(v[0]) === norm(src.company) && v[13] !== undefined && v[13] !== '';
return { json: {
  company: src.company, row: src.row,
  event: ok ? 'created' : 'error',
  detail: ok ? `Scoring record created. Total ${v[13]}, ${v[14]}, complexity ${v[15]}. ${src.summary}`
             : `Row ${src.row} was written but the read-back did not match (found: ${JSON.stringify(v.slice(0, 2))}). Check the row before retrying.`,
} };

const src = $('Is new record?').item.json;
const e = $json.error || {};
return { json: { company: src.company, row: src.row, event: 'error',
  detail: 'Write to ICP Scoring failed: ' + (e.message || e.description || JSON.stringify(e)).slice(0, 400) + '. Will retry on the next run.' } };
